    def largestPalindrome(self, n: int, k: int) -> str:
        if k in (1, 3, 9):
            return "9" * n

        if k == 2:
            if n == 1:
                return "8"
            return "8" + "9" * (n - 2) + "8"

        if k == 5:
            if n == 1:
                return "5"
            return "5" + "9" * (n - 2) + "5"

        if k == 4:
            if n <= 3:
                return "8" * n
            return "88" + "9" * (n - 4) + "88"

        if k == 8:
            if n <= 5:
                return "8" * n
            return "888" + "9" * (n - 6) + "888"

        if k == 6:
            if n == 1:
                return "6"
            if n == 2:
                return "66"
            if n % 2 == 1:
                half = (n - 3) // 2
                return "8" + "9" * half + "8" + "9" * half + "8"
            else:
                half = (n - 4) // 2
                return "8" + "9" * half + "77" + "9" * half + "8"

        if k == 7:
            if n == 1:
                return "7"
            if n == 2:
                return "77"

            # Powers of 10 modulo 7 follow a cycle of length 6: [1, 3, 2, 6, 4, 5]
            p10 = [1, 3, 2, 6, 4, 5]

            # Calculate (10^n - 1) % 7, which is the remainder of "99...9" (n times) divided by 7
            base_mod = (p10[n % 6] - 1) % 7
            if base_mod == 0:
                return "9" * n

            if n % 2 == 1:
                mid = n // 2
                w = p10[mid % 6]
                for d in range(9, -1, -1):
                    # Changing the middle digit from 9 to d reduces the value by (9 - d) * 10^mid
                    if (base_mod - (9 - d) * w) % 7 == 0:
                        return "9" * mid + str(d) + "9" * mid
            else:
                mid1 = n // 2 - 1
                mid2 = n // 2
                w = (p10[mid1 % 6] + p10[mid2 % 6]) % 7
                for d in range(9, -1, -1):
                    # Changing the two middle digits from 9 to d reduces the value by (9 - d) * (10^mid1 + 10^mid2)
                    if (base_mod - (9 - d) * w) % 7 == 0:
                        return "9" * mid1 + str(d) * 2 + "9" * mid1

        return ""
