from collections import defaultdict

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')

        def at_least(target_k: int) -> int:
            vowel_count = defaultdict(int)
            consonants = 0
            ans = 0
            left = 0
            n = len(word)

            for right in range(n):
                if word[right] in vowels:
                    vowel_count[word[right]] += 1
                else:
                    consonants += 1

                while len(vowel_count) == 5 and consonants >= target_k:
                    ans += n - right
                    if word[left] in vowels:
                        vowel_count[word[left]] -= 1
                        if vowel_count[word[left]] == 0:
                            del vowel_count[word[left]]
                    else:
                        consonants -= 1
                    left += 1
            return ans

        return at_least(k) - at_least(k + 1)
