class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        ans = 1
        n, m = len(s), len(t)

        for i in range(n + 1):
            for j in range(i, n + 1):
                sub_s = s[i:j]
                len_s = j - i
                for k in range(m + 1):
                    for l in range(k, m + 1):
                        len_t = l - k
                        if len_s + len_t <= ans:
                            continue
                        sub_t = t[k:l]
                        combined = sub_s + sub_t
                        if combined == combined[::-1]:
                            ans = len_s + len_t

        return ans
